import React, { useEffect, useState } from 'react';
import { formatDuration } from '../utils/dateUtils';
import { apiUrl } from '../data/chartsData';
import { apiService } from '../services/apiService';

interface CallStats {
 incoming: {
    count: number;
    total_duration: number;
  };
  outgoing: {
    count: number;
    total_duration: number;
  };
  total: {
    count: number;
    total_duration: number;
 };
}

interface CallFilters {
  startDate: Date | null;
  endDate: Date | null;
  caller: string;
  callee: string;
  metadataFilters?: Record<string, string>;
}

interface CallStatisticsProps {
  filters: CallFilters;
  refreshTrigger?: number; // Add a trigger prop to refresh stats when filters change
}

const CallStatistics: React.FC<CallStatisticsProps> = ({ filters, refreshTrigger }) => {
  const [stats, setStats] = useState<CallStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchStats = async () => {
      if (!filters.startDate || !filters.endDate) {
        setError('Start date and end date are required');
        setLoading(false);
        return;
      }

      setLoading(true);
      setError(null);
      
      try {
        const statsFilters = {
          startDate: filters.startDate.toISOString(),
          endDate: filters.endDate.toISOString(),
          caller: filters.caller || '%',
          callee: filters.callee || '%',
          metadata_filters: filters.metadataFilters || {}
        };

        const response = await apiService.post(`${apiUrl}backend/calls/stats`, statsFilters);
        setStats(response);
      } catch (err) {
        console.error('Error fetching call statistics:', err);
        setError('Failed to load call statistics');
      } finally {
        setLoading(false);
      }
    };

    fetchStats();
  }, [filters, refreshTrigger]);

  if (loading) {
    return (
      <div className="call-statistics">
        <h3>Статистика звонков</h3>
        <div className="loading">Загрузка статистики...</div>
      </div>
    );
  }

 if (error || !stats) {
    return (
      <div className="call-statistics">
        <h3>Статистика звонков</h3>
        <div className="error">Ошибка: {error || 'No statistics available'}</div>
      </div>
    );
  }

  return (
    <div className="call-statistics">
      <h3>Статистика звонков:</h3>
      <div className="statistics-container">
        <div className="statistic-item">
          <h4>Вх: {stats.incoming.count}</h4>
          <p>({formatDuration(stats.incoming.total_duration)})</p>
        </div>
        <div className="statistic-item">
          <h4>Исх: {stats.outgoing.count}</h4>
          <p>({formatDuration(stats.outgoing.total_duration)})</p>
        </div>
        <div className="statistic-item">
          <h4>Всего: {stats.total.count}</h4>
          <p>({formatDuration(stats.total.total_duration)})</p>
        </div>
      </div>
    </div>
  );
};

export default CallStatistics;