import { useState, useEffect, useContext } from 'react';
import { NavigationContext } from '../context/navContext';
import Table from '../components/Table';
import { apiService } from '../services/apiService';
import CallCardElement from '../components/CallCard';
import ReactDatePicker from 'react-datepicker';
import "react-datepicker/dist/react-datepicker.css";
import { apiUrl } from '../data/chartsData';
import CallStatistics from '../components/CallStatistics';
import { MetadataMapping } from '../models';

export function MainContent() {
    const Inav = useContext(NavigationContext);

    const mainActiveClassname = Inav.navigationOpen ? 'active' : '';
    const mainClassnames = ['main', mainActiveClassname];
    const [startDate, setStartDate] = useState<Date | null>(new Date());
    const [endDate, setEndDate] = useState<Date | null>(new Date(Date.now() - (3600 * 1000 * 24 * 365)));
    const [limit, setLimit] = useState<number>(10);
    const [offset, setOffset] = useState<number>(0);
    const [caller, setCaller] = useState<string>("%");
    const [callee, setCallee] = useState<string>("%");
    const [dataTable, setDataTable] = useState([]);
    const [callid, setCallid] = useState("");
    const [item, setItem] = useState([]);
    const [autoplay, setAutoplay] = useState(false);
    const [playingCallId, setPlayingCallId] = useState<string | null>(null);
    const [isAdmin, setIsAdmin] = useState(false);
    const [metadataMappings, setMetadataMappings] = useState<MetadataMapping[]>([]);
    const [visibleColumns, setVisibleColumns] = useState<Set<string>>(new Set());
    const [metadataFilters, setMetadataFilters] = useState<Record<string, string>>({});

    useEffect(() => {
        // Check if user is admin by decoding the token
        const token = localStorage.getItem('access_token');
        if (token) {
            try {
                const payload = JSON.parse(atob(token.split('.')[1]));
                const userRole = payload.role || 'user';
                setIsAdmin(userRole === 'admin');
            } catch (error) {
                console.error('Error decoding token:', error);
                setIsAdmin(false);
            }
        }
        updateData();
        fetchMetadataMappings();
    }, [limit, offset]);

    const fetchMetadataMappings = async () => {
        try {
            const response = await apiService.get(`${apiUrl}backend/metadata-mappings/active-public`);
            if (response) {
                setMetadataMappings(response);
                // Initialize visible columns - make all active mappings visible by default
                const initialVisibleColumns = new Set<string>();
                response.forEach((mapping: MetadataMapping) => {
                    initialVisibleColumns.add(mapping.display_name);
                });
                setVisibleColumns(initialVisibleColumns);
            }
        } catch (error) {
            console.error('Error fetching metadata mappings:', error);
        }
    };

    function updateData() {
        let callsFilter = {
            limit: limit,
            offset: offset,
            startDate: startDate,
            endDate: endDate,
            caller: caller,
            callee: callee,
            metadata_filters: metadataFilters
        };
        console.log(callsFilter);
        apiService.post(`${apiUrl}backend/calls/`, callsFilter)
            .then((res: any) => {
                if (res && res.length > 0) {
                    setDataTable(res); // Обновляем таблицу данными
                } else {
                    setDataTable([]); // Очищаем таблицу, если данных нет
                    setOffset(Math.max(offset - limit, 0)); // Возвращаем offset на предыдущую страницу
                }
            })
            .catch((err: any) => {
                console.log(err);
                setDataTable([]); // Очищаем таблицу в случае ошибки
            });
    }

    // Combine base columns with metadata columns based on visibility
    const column = [
        { heading: 'call_start_ts', value: 'call_start_ts' },
        { heading: 'caller', value: 'caller' },
        { heading: 'callee', value: 'calle' },
        { heading: 'duration', value: 'duration' },
        { heading: 'direction', value: 'direction' },
        ...metadataMappings
            .filter(mapping => visibleColumns.has(mapping.display_name))
            .map(mapping => ({
                heading: mapping.display_name,
                value: mapping.display_name // This will be the column header name that appears in the data
            }))
    ];

    const setCall = (call: string, item: any) => {
        setCallid(call);
        setItem(item);
        setPlayingCallId(call); // Set the currently playing call ID
        setAutoplay(true); // Enable autoplay for the selected call
        console.log(item);
        return false;
    };

    const handlePrevious = () => {
        const newOffset = Math.max(offset - limit, 0); // Убедимся, что offset не станет отрицательным
        setOffset(newOffset);
    };

    const handleNext = () => {
        setOffset(offset + limit);
    };

    const toggleColumnVisibility = (columnName: string) => {
        setVisibleColumns(prev => {
            const newSet = new Set(prev);
            if (newSet.has(columnName)) {
                newSet.delete(columnName);
            } else {
                newSet.add(columnName);
            }
            return newSet;
        });
    };

    const handleMetadataFilterChange = (mapping: MetadataMapping, value: string) => {
        setMetadataFilters(prev => ({
            ...prev,
            [mapping.field_key]: value
        }));
    };

    const resetMetadataFilters = () => {
        setMetadataFilters({});
    };

    const formatMetadataValue = (value: any, fieldType: string) => {
        if (value === null || value === undefined) {
            return 'N/A';
        }
        
        switch (fieldType) {
            case 'date':
                // Try to parse as date if it's a string
                if (typeof value === 'string') {
                    const date = new Date(value);
                    return isNaN(date.getTime()) ? String(value) : date.toLocaleDateString();
                }
                return new Date(value).toLocaleDateString();
            case 'boolean':
                return typeof value === 'boolean' ?
                    (value ? 'True' : 'False') :
                    (String(value).toLowerCase() === 'true' ? 'True' : 'False');
            case 'number':
                return Number(value).toLocaleString();
            case 'json':
                return JSON.stringify(value);
            default:
                return String(value);
        }
    };

    return (
        <div className={mainClassnames.join(' ')}>
            <CallCardElement callid={callid} item={item} autoplay={autoplay} setAutoplay={setAutoplay} />
            <div className="details">
                <div className='FiltersForm'>
                    {isAdmin && (
                        <div className="admin-indicator">
                            <span style={{ backgroundColor: '#28a745', color: 'white', padding: '5px 10px', borderRadius: '4px', fontSize: '14px', fontWeight: 'bold' }}>
                                ADMIN
                            </span>
                        </div>
                    )}
                    <button onClick={() => { updateData(); setOffset(0); }}>UPDATE</button>
                    {isAdmin && (
                        <button onClick={() => {
                            setCaller('%');
                            setCallee('%');
                            setStartDate(new Date(Date.now() - (3600 * 1000 * 24 * 365))); // A year ago
                            setEndDate(new Date());
                        }}>Reset Filters (Admin)</button>
                    )}
                    <span>StartDate</span>
                    <ReactDatePicker
                        selected={endDate}
                        onChange={(date) => setEndDate(date)}
                        showTimeSelect
                        timeFormat="HH:mm"
                        timeIntervals={15}
                        dateFormat="dd.MM.yyyy HH:mm"
                    />
                    <span>EndDate</span>
                    <ReactDatePicker
                        selected={startDate}
                        onChange={(date) => setStartDate(date)}
                        showTimeSelect
                        timeFormat="HH:mm"
                        timeIntervals={15}
                        dateFormat="dd.MM.yyyy HH:mm"
                    />
                    <span>Caller</span>
                    <input type="text" value={caller} onChange={(e) => { setCaller(e.target.value); }} />
                    <span>Callee</span>
                    <input type="text" value={callee} onChange={(e) => { setCallee(e.target.value); }} />

                    {/* Metadata Filters */}
                    {metadataMappings.length > 0 && (
                        <div className="metadata-filters" style={{ marginTop: '20px', padding: '15px', border: '1px solid #ddd', borderRadius: '4px', backgroundColor: '#f9f9f9' }}>
                            <h4 style={{ marginBottom: '15px', color: '#333' }}>Metadata Filters</h4>
                            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(250px, 1fr))', gap: '15px' }}>
                                {metadataMappings.map(mapping => (
                                    <div key={mapping.mapping_id}>
                                        <label style={{ display: 'block', marginBottom: '5px', fontWeight: 'bold' }}>{mapping.display_name}</label>
                                        <input
                                            type="text"
                                            placeholder={`Filter by ${mapping.display_name}`}
                                            value={metadataFilters[mapping.field_key] || ''}
                                            onChange={(e) => handleMetadataFilterChange(mapping, e.target.value)}
                                            style={{ width: '100%', padding: '8px', border: '1px solid #ccc', borderRadius: '4px' }}
                                        />
                                    </div>
                                ))}
                            </div>
                            <div style={{ marginTop: '15px', display: 'flex', gap: '10px' }}>
                                <button 
                                    onClick={updateData} 
                                    style={{ padding: '8px 15px', backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
                                >
                                    Apply Metadata Filters
                                </button>
                                <button 
                                    onClick={resetMetadataFilters} 
                                    style={{ padding: '8px 15px', backgroundColor: '#6c757d', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
                                >
                                    Reset Metadata Filters
                                </button>
                            </div>
                        </div>
                    )}

                    {/* Column Visibility Controls */}
                    {metadataMappings.length > 0 && (
                        <div className="column-visibility" style={{ marginTop: '20px', padding: '15px', border: '1px solid #ddd', borderRadius: '4px', backgroundColor: '#f9f9f9' }}>
                            <h4 style={{ marginBottom: '15px', color: '#333' }}>Column Visibility</h4>
                            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '15px' }}>
                                {metadataMappings.map(mapping => (
                                    <label key={mapping.mapping_id} style={{ display: 'flex', alignItems: 'center', cursor: 'pointer' }}>
                                        <input
                                            type="checkbox"
                                            checked={visibleColumns.has(mapping.display_name)}
                                            onChange={() => toggleColumnVisibility(mapping.display_name)}
                                            style={{ marginRight: '5px' }}
                                        />
                                        {mapping.display_name}
                                    </label>
                                ))}
                            </div>
                        </div>
                    )}
                </div>
                <div className="recentOrders">
                    <div className="cardHeader">
                        <h2>Звонки: {dataTable.length}</h2>
                        <div className='paginator'>
                            <select
                                name="paginatorlimit"
                                id="paginatorlimit"
                                onChange={(e) => { setLimit(Number(e.target.value)); setOffset(0); }}
                            >
                                <option value="10">10</option>
                                <option value="100">100</option>
                                <option value="500">500</option>
                                <option value="1000">1000</option>
                            </select>
                            <button onClick={handlePrevious}>&lt;</button>
                            <button onClick={handleNext}>&gt;</button>
                            <span>Страница: {Math.floor(offset / limit) + 1}</span>
                        </div>
                    </div>
                    <div className="table-container">
                        <Table data={dataTable} column={column} setCallid={setCall} playingCallId={playingCallId} metadataMappings={metadataMappings} />
                    </div>
                    <div className="call-statistics-container">
                        <CallStatistics
                            filters={{
                                startDate: endDate,
                                endDate: startDate,
                                caller: caller,
                                callee: callee,
                                metadataFilters: metadataFilters
                            }}
                            refreshTrigger={dataTable.length}
                        />
                    </div>
                </div>
            </div>
        </div>
    );
}