import React from 'react';
import { MainContent } from './pages/MainContent';
import { Navigation } from './components/Navigation';
import { Route, Routes } from 'react-router-dom'
import { ChartContent } from './pages/ChartContent';
import { TextSearch } from './pages/TextSearchPage';
import FileForm from './pages/SendFileForm';
import EditableTable from './pages/TagEditor'
import LoginPage from './pages/LoginPage';
import AdminPanel from './pages/AdminPanel';
import UserProfile from './pages/UserProfile';
import ProtectedRoute from './components/ProtectedRoute';
import Unauthorized from './pages/Unauthorized';


function App() {
  return (
    <div className="container">
      <Navigation/>
      <Routes>
        <Route path='/' element={<ProtectedRoute><MainContent /></ProtectedRoute>} />
        <Route path='/charts' element={<ProtectedRoute><ChartContent /></ProtectedRoute>} />
        <Route path='/textsearch' element={<ProtectedRoute><TextSearch /></ProtectedRoute>} />
        <Route path='/sendfile' element={<ProtectedRoute><FileForm /></ProtectedRoute>} />
        <Route path='/tags' element={<ProtectedRoute><EditableTable /></ProtectedRoute>} />
        <Route path='/profile' element={<ProtectedRoute><UserProfile /></ProtectedRoute>} />
        <Route path='/login' element={<LoginPage />} />
        <Route path='/admin' element={<ProtectedRoute requiredRole="admin"><AdminPanel /></ProtectedRoute>} />
        <Route path='/unauthorized' element={<Unauthorized />} />
      </Routes>
    </div>
    );
}

export default App;
