import React from 'react';
import { menus } from '../data/menus';
import { Menu } from './menu';
import { IoIosMenu} from "react-icons/io";
import { NavigationContext } from '../context/navContext';
import { Link, useNavigate } from 'react-router-dom'; // Import Link and useNavigate
import { authService } from '../services/authService';
import { addIcons } from 'ionicons';
import { logInOutline, logOutOutline, personOutline } from 'ionicons/icons';
import { IonIcon } from '@ionic/react';

// Add the login/logout icons
addIcons({
  'log-in-outline': logInOutline,
  'log-out-outline': logOutOutline,
  'person-outline': personOutline
});


export function Navigation(){
    const Inav = React.useContext(NavigationContext)
    const navigate = useNavigate(); // Initialize useNavigate

    const navigationActiveClassname = Inav.navigationOpen ? 'active' : ''
    const navigationClassnames = ['navigation',navigationActiveClassname]

    const handleLogout = () => {
        authService.logout(); // Use authService for logout
    };

    // Function to get username from token
    const getUsernameFromToken = () => {
        const token = localStorage.getItem('access_token');
        if (token) {
            try {
                const payload = JSON.parse(atob(token.split('.')[1]));
                return payload.sub || 'User'; // 'sub' is the standard JWT claim for subject (username)
            } catch (error) {
                console.error('Error decoding token:', error);
                return 'User';
            }
        }
        return null;
    };

    // Function to get user role from token
    const getUserRoleFromToken = () => {
        const token = localStorage.getItem('access_token');
        if (token) {
            try {
                const payload = JSON.parse(atob(token.split('.')[1]));
                return payload.role || 'user'; // Default role is 'user'
            } catch (error) {
                console.error('Error decoding token:', error);
                return 'user';
            }
        }
        return null;
    };

    const username = getUsernameFromToken();
    const isLoggedIn = !!username; // Check if user is logged in based on username

    return(
        
            <div className={navigationClassnames.join(' ')}>
                <ul>
                    <div className="toggle" onClick={() => Inav.toggle()}>
                        <IoIosMenu/>
                    </div>
                    {menus.filter(menu => menu.title !== 'Admin Panel').map(menuP =>  <Menu key={menuP.url} menu={menuP}/>)}
                    {/* Spacer to push user info to bottom */}
                    <div className="spacer"></div>
                    {/* Admin Panel after spacer - only for admin users */}
                    {isLoggedIn && getUserRoleFromToken() === 'admin' &&
                        menus.filter(menu => menu.title === 'Admin Panel').map(menuP =>  <Menu key={menuP.url} menu={menuP}/>)
                    }
                    {isLoggedIn ? (
                        <>
                            <li className="user-info">
                                <Link to="/profile" onClick={() => Inav.toggle()} className="user-info-link">
                                    <span className="icon">
                                        <IonIcon icon={personOutline} title={username} aria-label={username}/>
                                    </span>
                                    <span className="title">{username}</span>
                                </Link>
                            </li>
                            <li>
                                <a href="#" onClick={handleLogout}>
                                    <span className="icon">
                                        <IonIcon icon={logOutOutline} title="Logout" aria-label="Logout"/>
                                    </span>
                                    <span className="title">Logout</span>
                                </a>
                            </li>
                        </>
                    ) : (
                        <li>
                            <Link to="/login" onClick={() => Inav.toggle()}>
                                <span className="icon">
                                    <IonIcon icon={logInOutline} title="Login" aria-label="Login"/>
                                </span>
                                <span className="title">Login</span>
                            </Link>
                        </li>
                    )}
                </ul>
            </div>
    );
};
