import { authService } from './authService';
import { apiUrl } from '../data/chartsData';

export interface ApiKey {
    api_key_id: number;
    name: string;
    description?: string;
    key_prefix: string;
    created_at: string;
    last_used_at?: string;
}

export interface ApiKeyCreateResponse extends ApiKey {
    api_key: string;
}

export const apiKeysService = {
    async getApiKeys(): Promise<ApiKey[]> {
        const response = await fetch(`${apiUrl}backend/api-keys/`, {
            method: 'GET',
            headers: {
                'Content-Type': 'application/json',
                ...authService.getAuthHeader(),
            },
        });

        if (response.status === 401) {
            authService.logout();
            return [];
        }

        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }

        return response.json();
    },

    async createApiKey(name: string, description?: string): Promise<ApiKeyCreateResponse> {
        const response = await fetch(`${apiUrl}backend/api-keys/`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                ...authService.getAuthHeader(),
            },
            body: JSON.stringify({ name, description }),
        });

        if (response.status === 401) {
            authService.logout();
            throw new Error('Unauthorized');
        }

        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }

        return response.json();
    },

    async deleteApiKey(apiKeyId: number): Promise<void> {
        const response = await fetch(`${apiUrl}backend/api-keys/${apiKeyId}`, {
            method: 'DELETE',
            headers: {
                'Content-Type': 'application/json',
                ...authService.getAuthHeader(),
            },
        });

        if (response.status === 401) {
            authService.logout();
            return;
        }

        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }
    },

    async getApiKey(apiKeyId: number): Promise<ApiKey> {
        const response = await fetch(`${apiUrl}backend/api-keys/${apiKeyId}`, {
            method: 'GET',
            headers: {
                'Content-Type': 'application/json',
                ...authService.getAuthHeader(),
            },
        });

        if (response.status === 401) {
            authService.logout();
            throw new Error('Unauthorized');
        }

        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }

        return response.json();
    },
};
